package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct {
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLeapFlag string // PIC X len=1 = "N"
var WsQ int64 // PIC 9(4) len=4 = 0
var WsR4 int64 // PIC 9(3) len=3 = 0
var WsR100 int64 // PIC 9(3) len=3 = 0
var WsR400 int64 // PIC 9(3) len=3 = 0
var WsMaxDay int64 // PIC 99 len=2 = 0
var WsValid int64 // PIC 99 len=2 = 0
var WsBadMonth int64 // PIC 99 len=2 = 0
var WsBadDay int64 // PIC 99 len=2 = 0

var dateRec DateRec

var dateFile *os.File
var scanner *bufio.Scanner

// helper to avoid unused import
var _ = decimal.NewFromInt(0)

func initVars() {
	WsEofFlag = "N"
	WsLeapFlag = "N"
	WsQ = 0
	WsR4 = 0
	WsR100 = 0
	WsR400 = 0
	WsMaxDay = 0
	WsValid = 0
	WsBadMonth = 0
	WsBadDay = 0
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isLeap() bool {
	return WsLeapFlag == "Y"
}

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatNum(v int64, digits int) string {
	if digits <= 0 {
		return ""
	}
	mod := pow10(digits)
	// keep low-order digits (truncate high-order)
	// COBOL stores only low-order digits; for positive values it's v % mod
	// handle negative just in case
	vm := v % mod
	if vm < 0 {
		vm += mod
	}
	s := strconv.FormatInt(vm, 10)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	// if somehow longer (should not happen due to mod) truncate high-order
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func parseNum(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	// COBOL numeric fields contain digits only; strip spaces
	// If non-digit present, treat as 0 per safe fallback
	trimmed = strings.TrimSpace(s)
	// remove leading/trailing spaces already, but keep inner?
	// parse as integer if possible
	// Keep only digits and optional sign
	sign := int64(1)
	if strings.HasPrefix(trimmed, "-") {
		sign = -1
		trimmed = trimmed[1:]
	} else if strings.HasPrefix(trimmed, "+") {
		trimmed = trimmed[1:]
	}
	trimmed = strings.TrimSpace(trimmed)
	if trimmed == "" {
		return 0
	}
	// ensure all digits
	for _, ch := range trimmed {
		if ch < '0' || ch > '9' {
			// non-digit => 0
			return 0
		}
	}
	v, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		return 0
	}
	return sign * v
}

func storePic99(v int64) int64 {
	mod := int64(100)
	vm := v % mod
	if vm < 0 {
		vm += mod
	}
	return vm
}
func storePic9_4(v int64) int64 {
	mod := int64(10000)
	vm := v % mod
	if vm < 0 {
		vm += mod
	}
	return vm
}
func storePic9_3(v int64) int64 {
	mod := int64(1000)
	vm := v % mod
	if vm < 0 {
		vm += mod
	}
	return vm
}

// Paragraphs

func READPARA() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		// LINE SEQUENTIAL: pad with spaces on the right if shorter than record length
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		dateRec.DtId = line[0:4]
		dateRec.DtYyyy = parseNum(line[4:8])
		dateRec.DtMm = parseNum(line[8:10])
		dateRec.DtDd = parseNum(line[10:12])
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	WsQ = dateRec.DtYyyy / 4
	WsR4 = dateRec.DtYyyy - WsQ*4
	WsQ = storePic9_4(WsQ)
	WsR4 = storePic9_3(WsR4)
	// DIVIDE DT-YYYY BY 100 GIVING WS-Q REMAINDER WS-R100
	WsQ = dateRec.DtYyyy / 100
	WsR100 = dateRec.DtYyyy - WsQ*100
	WsQ = storePic9_4(WsQ)
	WsR100 = storePic9_3(WsR100)
	// DIVIDE DT-YYYY BY 400 GIVING WS-Q REMAINDER WS-R400
	WsQ = dateRec.DtYyyy / 400
	WsR400 = dateRec.DtYyyy - WsQ*400
	WsQ = storePic9_4(WsQ)
	WsR400 = storePic9_3(WsR400)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	WsMaxDay = storePic99(WsMaxDay)
}

func PROCESSPARA() {
	LEAPPARA()
	// EVALUATE TRUE WHEN DT-MM <1 OR DT-MM>12
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = storePic99(WsBadMonth + 1)
		// DISPLAY DT-ID " BAD MONTH " DT-MM
		fmt.Println(dateRec.DtId + " BAD MONTH " + formatNum(dateRec.DtMm, 2))
	} else {
		DAYSPARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = storePic99(WsBadDay + 1)
			fmt.Println(dateRec.DtId + " BAD DAY " + formatNum(dateRec.DtDd, 2) + " MAX " + formatNum(WsMaxDay, 2))
		} else {
			WsValid = storePic99(WsValid + 1)
			fmt.Println(dateRec.DtId + " VALID " + formatNum(dateRec.DtYyyy, 4) + "-" + formatNum(dateRec.DtMm, 2) + "-" + formatNum(dateRec.DtDd, 2))
		}
	}
	READPARA()
}

func MAINPARA() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty? But spec says read from file.
		// To match COBOL OPEN INPUT behavior, error is fatal.
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer dateFile.Close()
	scanner = bufio.NewScanner(dateFile)
	// Allow long lines
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE DATE-FILE (defer)
	fmt.Println("VALID: " + formatNum(WsValid, 2) + " BAD MONTH: " + formatNum(WsBadMonth, 2) + " BAD DAY: " + formatNum(WsBadDay, 2))
}

func main() {
	initVars()
	MAINPARA()
}
